INSERT INTO control_edge_usage_events(tenant_id,executor_id,session_id,seq,kind,run_id,occurred_at_ms,started_seq,source_session_id,provider,model,protocol,event_json)
SELECT e.tenant_id,e.executor_id,e.session_id,e.seq,(e.event_json::jsonb #>> '{type}'),(e.event_json::jsonb #>> '{run_id}'),CAST((e.event_json::jsonb #>> '{occurred_at_ms}') AS BIGINT),CAST((e.event_json::jsonb #>> '{started_seq}') AS BIGINT),(e.event_json::jsonb #>> '{source_session_id}'),(e.event_json::jsonb #>> '{route,provider}'),(e.event_json::jsonb #>> '{route,model}'),(e.event_json::jsonb #>> '{route,protocol}'),e.event_json
FROM control_edge_events e WHERE (e.event_json::jsonb #>> '{type}') IN ('provider_usage_started','provider_usage_finished')
